import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        long prev2 = 0, prev = 0, last = 0;
        for (int t = 0; t < n; t++) {
            String token = next();
            long value = Long.parseLong(token), shift = 1;
            for (int i = 0; i < token.length(); i++) shift *= 10;
            // keep the element alone, or join it with the previous original element
            long current = Math.max(prev + value, prev2 + last * shift + value);
            prev2 = prev;
            prev = current;
            last = value;
        }
        System.out.println(prev);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"strconv"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	var prev2, prev, last int64
	for t := 0; t < n; t++ {
		token := next()
		value, _ := strconv.ParseInt(string(token), 10, 64)
		shift := int64(1)
		for range token {
			shift *= 10
		}
		// keep the element alone, or join it with the previous original element
		current := max(prev+value, prev2+last*shift+value)
		prev2, prev, last = prev, current, value
	}
	fmt.Println(prev)
}
